export const PROJECT_KEY_MAX_LENGTH = 4;

/**
 * Derives a project key that collides with nothing in `taken`, the way
 * `uniqueSlug` does for addresses: appends `2`, `3`, … and trims the base so
 * the key never exceeds `PROJECT_KEY_MAX_LENGTH` characters.
 */
export function uniqueProjectKey(input: string, taken: Iterable<string>): string {
  const base =
    input.toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, PROJECT_KEY_MAX_LENGTH) ||
    "TASK";
  const used = new Set(Array.from(taken, (key) => key.toUpperCase()));
  if (!used.has(base)) return base;

  for (let suffix = 2; suffix < 1_000; suffix += 1) {
    const digits = String(suffix);
    const room = PROJECT_KEY_MAX_LENGTH - digits.length;
    if (room < 1) break;
    const candidate = `${base.slice(0, room)}${digits}`;
    if (!used.has(candidate)) return candidate;
  }
  throw new InvalidSlugError(base, "exhausted unique project keys");
}
EOF

